/**
 * Bind or unbind an event callback.
 *
 * @param {string} action - 'attach' or 'detach'
 * @param {string} eventProp - Event property name in state
 * @param {string} type - Body type ('static', 'kinematic', etc.)
 * @param {number} id - Body index
 */
export function bindEventCB(action: string, eventProp: string, type: string, id: number): void;
export function attachEnterZoneCB(id: any): void;
export function detachEnterZoneCB(id: any): void;
export function attachLeaveZoneCB(id: any): void;
export function detachLeaveZoneCB(id: any): void;
export function attachInReachCB(id: any): void;
export function detachInReachCB(id: any): void;
export function attachCollideCB(type: any, id: any): void;
export function detachCollideCB(type: any, id: any): void;
export function attachSitCB(): void;
export function detachSitCB(): void;
export function attachStopCollideCB(type: any, id: any): void;
export function detachStopCollideCB(type: any, id: any): void;
export function attachHitCB(type: any, id: any): void;
export function detachHitCB(type: any, id: any): void;
export function attachPointerIntersectCB(type: any, id: any): void;
export function detachPointerIntersectCB(type: any, id: any): void;
export function attachWeaponFireCB(weaponIndex: any): void;
export function detachWeaponFireCB(weaponIndex: any): void;
export function attachWeaponHitCB(weaponIndex: any): void;
export function detachWeaponHitCB(weaponIndex: any): void;
export function attachWeaponExplodeCB(weaponIndex: any): void;
export function detachWeaponExplodeCB(weaponIndex: any): void;
export function attachWeaponSpawnCB(weaponIndex: any): void;
export function detachWeaponSpawnCB(weaponIndex: any): void;
export function attachWeaponDespawnCB(weaponIndex: any): void;
export function detachWeaponDespawnCB(weaponIndex: any): void;
export function attachEventGate(cb: any): Promise<void>;
export function detachEventGate(): Promise<void>;
export function click(): Promise<void>;
